  // between integer grid points.
  function _valueNoise1D(x, seed) {
    seed = (seed | 0);
    const xi = Math.floor(x);
    const xf = x - xi;
    const a = (_hashInt(xi + seed * 1597334677) / 0x7FFFFFFF) * 2 - 1;
    const b = (_hashInt(xi + 1 + seed * 1597334677) / 0x7FFFFFFF) * 2 - 1;
    const t = xf * xf * (3 - 2 * xf);    // smoothstep
    return a + (b - a) * t;
  }
