    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const xf = x - xi;
    const yf = y - yi;
    const a = (_hashInt(xi * 374761393 + yi * 668265263 + s) / 0x7FFFFFFF) * 2 - 1;
    const b = (_hashInt((xi+1) * 374761393 + yi * 668265263 + s) / 0x7FFFFFFF) * 2 - 1;
    const c = (_hashInt(xi * 374761393 + (yi+1) * 668265263 + s) / 0x7FFFFFFF) * 2 - 1;
    const d = (_hashInt((xi+1) * 374761393 + (yi+1) * 668265263 + s) / 0x7FFFFFFF) * 2 - 1;
    const u = xf * xf * (3 - 2 * xf);
    const v = yf * yf * (3 - 2 * yf);
