                  // 14-bit pitch wheel where 8192 = center.
                  const m = (v * 64) | 0;
                  emitVLQ(pendingDelta); pendingDelta = 0;
                  emit(0xE0 | ch); emit(m & 0x7F); emit((m >> 7) & 0x7F);
