          triBBMin[t*3+2] = Math.min(z0, Math.min(z1, z2));
          triBBMax[t*3+0] = Math.max(x0, Math.max(x1, x2));
          triBBMax[t*3+1] = Math.max(y0, Math.max(y1, y2));
          triBBMax[t*3+2] = Math.max(z0, Math.max(z1, z2));
