            if (triBBMin[bX+1] < nMinY) nMinY = triBBMin[bX+1];
            if (triBBMin[bX+2] < nMinZ) nMinZ = triBBMin[bX+2];
            if (triBBMax[bX]   > nMaxX) nMaxX = triBBMax[bX];
            if (triBBMax[bX+1] > nMaxY) nMaxY = triBBMax[bX+1];
            if (triBBMax[bX+2] > nMaxZ) nMaxZ = triBBMax[bX+2];
            if (triCentroid[bX]   < cMinX) cMinX = triCentroid[bX];
            if (triCentroid[bX+1] < cMinY) cMinY = triCentroid[bX+1];
            if (triCentroid[bX+2] < cMinZ) cMinZ = triCentroid[bX+2];
            if (triCentroid[bX]   > cMaxX) cMaxX = triCentroid[bX];
            if (triCentroid[bX+1] > cMaxY) cMaxY = triCentroid[bX+1];
            if (triCentroid[bX+2] > cMaxZ) cMaxZ = triCentroid[bX+2];
