                resize: U('uResize'), scale: U('uScale'),
                camPos: U('uCamPos'), fogColor: U('uFogColor'), worldTint: U('uWorldTint'),
                fogFar: U('uFogFar'), fogCurve: U('uFogCurve'),
                pbrOn: U('uPbrOn'), pbrSunDir: U('uPbrSunDir'), pbrSunCol: U('uPbrSunCol'),
                pbrAmb: U('uPbrAmb'), pbrSkyDir: U('uPbrSkyDir'), pbrZen: U('uPbrZen'),
                pbrHor: U('uPbrHor'), pbrRaw: U('uPbrRaw'), pbrFogScale: U('uPbrFogScale'),
                pbrExposure: U('uPbrExposure'), hdrOut: U('uHdrOut'), pbrSat: U('uPbrSat'),
                terrSat: U('uTerrSat'), terrBright: U('uTerrBright'),
                pbrHmapOn: U('uPbrHmapOn'), pbrHmap: U('uPbrHmap'),
                pbrSkyTex: U('uPbrSkyTex'), pbrSkyOn: U('uPbrSkyOn'),
                pbrShadVP: U('uPbrShadVP'), pbrShadowOn: U('uPbrShadowOn'), pbrShadowMap: U('uPbrShadowMap'),
                pbrLP: U('uPbrLP'), pbrLC: U('uPbrLC'), pbrLR: U('uPbrLR'), pbrLN: U('uPbrLN'),
                pbrAOTex: U('uPbrAOTex'), pbrAOOn: U('uPbrAOOn'), pbrAOFull: U('uPbrAOFull'),
                atlas: U('uAtlas'), tileSize: U('uTileSize'),
                animOrigins: U('uAnimOrigins'), animCount: U('uAnimCount'), animScroll: U('uAnimScroll'),
                pbrWaterOn: U('uPbrWaterOn'), waterTime: U('uWaterTime'), lavaOrigin: U('uLavaOrigin'), dropletOrigin: U('uDropletOrigin'),
