      // at the same moment the verts are staged).
      _zbufGpuAlphaTriVert = new Int32Array(_ZBUF_GPU_ALPHA_MAX);
      _zbufGpuAlphaCent = new Float32Array(_ZBUF_GPU_ALPHA_MAX * 3);
      _zbufGpuAlphaKey = new Float32Array(_ZBUF_GPU_ALPHA_MAX);
      _zbufGpuAlphaOrder = new Int32Array(_ZBUF_GPU_ALPHA_MAX);
      _zbufGpuAlphaIdx = new Uint32Array(_ZBUF_GPU_ALPHA_MAX * 3);
