    'sampleTexture','sampleShadow','sampleCubemap','sampleCubemapLod',
    'texelFetch',
    // 3D pipeline -- depth-buffer / world-space / GPU helpers used by
    // games with a 3D renderer (Basil Blaster, etc). These all take
    // ints/floats and are validated at the engine level.
    'zbufInit','zbufActive','zbufMode','zbufClear','zbufFlush',
    'zbufTri','zbufGpuReady','zbufDebugDraw','zbufPerf','zbufPerfTick',
