    const callRe = /\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g;
    const userFns = new Set();
    const fnDeclRe = /\b(?:int|float|bool|string|void|map|set|any|Vec[234]|Mat4)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g;
    let fnm;
    while ((fnm = fnDeclRe.exec(code)) !== null) userFns.add(fnm[1]);
    const structDeclRe = /\bstruct\s+([A-Z][A-Za-z0-9_]*)/g;
    while ((fnm = structDeclRe.exec(code)) !== null) userFns.add(fnm[1]);
    // v1.6: tagged union variant constructors. Each variant in a union
    // body is callable as a constructor (e.g. `Ok(5)` for `union R { Ok(int v) }`).
    // Without this pass, the linter would flag every variant call as a
    // hallucinated builtin.
    const unionDeclRe = /\bunion\s+([A-Z][A-Za-z0-9_]*)\s*\{([^}]*)\}/g;
    let unm;
