    // naturally. But unqualified calls inside the namespace ARE found,
    // so harvest those as user-defined function names.
    const namespaceBodyRe = /\bnamespace\s+[A-Za-z_][A-Za-z0-9_]*\s*\{([\s\S]*?)\}/g;
    let nbm;
    while ((nbm = namespaceBodyRe.exec(code)) !== null) {
      const body = nbm[1];
      const innerFnRe = new RegExp(fnDeclRe.source, 'g');
      let ifm;
      while ((ifm = innerFnRe.exec(body)) !== null) {
        userFns.add(ifm[1]);
      }
    }
